/// A custom <see cref="JsonConverter{T}"/> for <see cref="ResponseError"/> that can be used
/// with the System.Text.Json source generator, since the built-in converter on
/// <see cref="ResponseError"/> is internal and inaccessible to source generation.
/// </summary>
internal sealed class ResponseErrorConverter : JsonConverter<ResponseError>
{
    public override ResponseError? Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
    {
        using var document = JsonDocument.ParseValue(ref reader);
        return ReadResponseError(document.RootElement);
    }

    public override void Write(Utf8JsonWriter writer, ResponseError value, JsonSerializerOptions options)
    {
        if (value is null)
        {
            writer.WriteNullValue();
            return;
        }

        writer.WriteStartObject();

        if (value.Code is not null)
        {
            writer.WriteString("code"u8, value.Code);
        }

        if (value.Message is not null)
        {
            writer.WriteString("message"u8, value.Message);
        }

        if (value.Target is not null)
        {
            writer.WriteString("target"u8, value.Target);
        }

        if (value.Details is not null)
        {
            writer.WriteStartArray("details"u8);
            foreach (var detail in value.Details)
            {
                Write(writer, detail, options);
            }
            writer.WriteEndArray();
        }

        if (value.InnerError is not null)
        {
            writer.WritePropertyName("innererror"u8);
            Write(writer, value.InnerError, options);
        }

        writer.WriteEndObject();
    }

    private static ResponseError? ReadResponseError(JsonElement element)
    {
        if (element.ValueKind == JsonValueKind.Null)
        {
            return null;
        }

        string? code = null;
        string? message = null;
        string? target = null;
        ResponseInnerError? innerError = null;
        System.Collections.Generic.List<ResponseError>? details = null;

        if (element.TryGetProperty("code", out var codeProp))
        {
            code = codeProp.GetString();
        }

        if (element.TryGetProperty("message", out var messageProp))
        {
            message = messageProp.GetString();
        }

        if (element.TryGetProperty("target", out var targetProp))
        {
            target = targetProp.GetString();
        }

        if (element.TryGetProperty("innererror", out var innerProp) && innerProp.ValueKind != JsonValueKind.Null)
        {
            innerError = ReadResponseInnerError(innerProp);
        }

        if (element.TryGetProperty("details", out var detailsProp) && detailsProp.ValueKind == JsonValueKind.Array)
        {
            details = new System.Collections.Generic.List<ResponseError>();
            foreach (var item in detailsProp.EnumerateArray())
            {
                var detail = ReadResponseError(item);
                if (detail is not null)
                {
                    details.Add(detail);
                }
            }
        }

        return new ResponseError(code, message, innerError, target, details);
    }

    private static ResponseInnerError? ReadResponseInnerError(JsonElement element)
    {
        if (element.ValueKind == JsonValueKind.Null)
        {
            return null;
        }

        string? code = null;
        ResponseInnerError? innerError = null;

        if (element.TryGetProperty("code", out var codeProp))
        {
            code = codeProp.GetString();
        }

        if (element.TryGetProperty("innererror", out var innerProp) && innerProp.ValueKind != JsonValueKind.Null)
        {
            innerError = ReadResponseInnerError(innerProp);
        }

        return new ResponseInnerError(code, innerError);
    }
